/**
 * @suppress
 */
public object FfiConverterBoolean: FfiConverter<Boolean, Byte> {
    override fun lift(value: Byte): Boolean {
        return value.toInt() != 0
    }

    override fun read(buf: ByteBuffer): Boolean {
        return lift(buf.get())
    }

    override fun lower(value: Boolean): Byte {
        return if (value) 1.toByte() else 0.toByte()
    }

    override fun allocationSize(value: Boolean) = 1UL

    override fun write(value: Boolean, buf: ByteBuffer) {
        buf.put(lower(value))
    }
}

/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}



/**
 * Enumeration for the different types of device.
 *
 * Firefox Accounts and the broader Sync universe separates devices into broad categories for
 * various purposes, such as distinguishing a desktop PC from a mobile phone.
 * Upon signin, the application should inspect the device it is running on and select an appropriate
 * [`DeviceType`] to include in its device registration record.
 *
 * A special variant in this enum, [`DeviceType::Unknown`] is used to capture
 * the string values we don't recognise. It also has a custom serde serializer and deserializer
 * which implements the following semantics:
 * * deserializing a `DeviceType` which uses a string value we don't recognise or null will return
 * `DeviceType::Unknown` rather than returning an error.
 * * serializing `DeviceType::Unknown` will serialize `null`.
 *
 * This has a few important implications:
 * * In general, `Option<DeviceType>` should be avoided, and a plain `DeviceType` used instead,
 * because in that case, `None` would be semantically identical to `DeviceType::Unknown` and
 * as mentioned above, `null` already deserializes as `DeviceType::Unknown`.
 * * Any unknown device types can not be round-tripped via this enum - eg, if you deserialize
 * a struct holding a `DeviceType` string value we don't recognize, then re-serialize it, the
 * original string value is lost. We don't consider this a problem because in practice, we only
 * upload records with *this* device's type, not the type of other devices, and it's reasonable
 * to assume that this module knows about all valid device types for the device type it is
 * deployed on.
 */

enum class DeviceType {
    
    DESKTOP,
    MOBILE,
    TABLET,
    VR,
    TV,
    UNKNOWN;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeDeviceType: FfiConverterRustBuffer<DeviceType> {
    override fun read(buf: ByteBuffer) = try {
        DeviceType.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: DeviceType) = 4UL

    override fun write(value: DeviceType, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * How the user's choice of engines to sync is modelled.
 */
sealed class EngineChoicesModel {
    
    /**
     * The legacy model: engine choices are shared by every device on the
     * account, via meta/global's declined engines.
     */
    data class Account(
        /**
         * Which engine states should be *changed* in the "account global" list (for
         * example, if the UI was used to change an engine's state since the last
         * sync).
         * Normally empty - only used for selection changes, does not reflect current actual choices.
         */
        val `enabledChanges`: Map<kotlin.String, kotlin.Boolean>) : EngineChoicesModel()
        
    {
        

        companion object
    }
    
    /**
     * Engine choices are specific to each device. Not yet ready for use
     * outside of testing.
     */
    object Device : EngineChoicesModel()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeEngineChoicesModel : FfiConverterRustBuffer<EngineChoicesModel>{
    override fun read(buf: ByteBuffer): EngineChoicesModel {
        return when(buf.getInt()) {
            1 -> EngineChoicesModel.Account(
                FfiConverterMapStringBoolean.read(buf),
                )
            2 -> EngineChoicesModel.Device
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EngineChoicesModel): ULong = when(value) {
        is EngineChoicesModel.Account -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterMapStringBoolean.allocationSize(value.`enabledChanges`)
            )
        }
        is EngineChoicesModel.Device -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: EngineChoicesModel, buf: ByteBuffer) {
        when(value) {
            is EngineChoicesModel.Account -> {
                buf.putInt(1)
                FfiConverterMapStringBoolean.write(value.`enabledChanges`, buf)
                Unit
            }
            is EngineChoicesModel.Device -> {
                buf.putInt(2)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterMapStringBoolean: FfiConverterRustBuffer<Map<kotlin.String, kotlin.Boolean>> {
    override fun read(buf: ByteBuffer): Map<kotlin.String, kotlin.Boolean> {
        val len = buf.getInt()
        return buildMap<kotlin.String, kotlin.Boolean>(len) {
            repeat(len) {
                val k = FfiConverterString.read(buf)
                val v = FfiConverterBoolean.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<kotlin.String, kotlin.Boolean>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterString.allocationSize(k) +
            FfiConverterBoolean.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<kotlin.String, kotlin.Boolean>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterString.write(k, buf)
            FfiConverterBoolean.write(v, buf)
        }
    }
}

